H["@lsp.type.property"] = { fg = "#eabeaa" }
H["@lsp.type.keyword"] = { fg = "#fa99b4" }
H["@lsp.type.modifier"] = { fg = "#fa99b4" }
H["@lsp.type.operator"] = { fg = "#ccbac5" }
H["@lsp.type.string"] = { fg = "#b7e6b7" }
H["@lsp.type.number"] = { fg = "#f0d6a0" }
H["@lsp.type.comment"] = { fg = "#bd9fb1", italic = true }
H["@lsp.mod.deprecated"] = { fg = "#bd9fb1", strikethrough = true }

for group, spec in pairs(H) do
  vim.api.nvim_set_hl(0, group, spec)
end

-- Terminal palette: ANSI 0-15 exactly as the kitty port.
vim.g.terminal_color_0 = "#6c4c60"
